from pathlib import Path
import re
p=Path('index.html'); h=p.read_text()
h=h.replace('<li><a href="#recursos" class="nav-link">Recursos</a></li>','<li><a href="recursos.html" class="nav-link" target="_blank" rel="noopener noreferrer">Recursos</a></li>')
h=re.sub(r'\s*<button type="button" class="btn link" data-service-key="[^"]+">Conocer más</button>','',h)
section='''        <section id="recursos" class="resources-section" aria-labelledby="recursos-heading"><div class="container"><p class="section-eyebrow">Biblioteca para acompañar en casa</p><h2 id="recursos-heading">Recursos gratuitos para acompañar el desarrollo</h2><p class="resources-intro">Materiales, juegos, explicaciones y guías para consultar a tu ritmo.</p><a class="btn btn-primary resources-library-link" href="recursos.html" target="_blank" rel="noopener noreferrer">Abrir biblioteca de recursos</a></div></section>\n\n'''
h=re.sub(r'        <!-- Sección Recursos: materiales de ejemplo disponibles dentro del sitio -->.*?        <!-- Diálogo reutilizable para servicios y recursos -->',section,h,flags=re.S)
h=re.sub(r'\n\s*<!-- Diálogo reutilizable para servicios y recursos -->.*?</dialog>\n','\n',h,flags=re.S)
h=h.replace('<a class="btn primary appointment-resource-action" href="#recursos">Ver recursos gratuitos</a>','<a class="btn primary appointment-resource-action" href="recursos.html" target="_blank" rel="noopener noreferrer">Ver recursos gratuitos</a>')
p.write_text(h)
Path('assets/recursos').mkdir(parents=True,exist_ok=True)
Path('assets/recursos/registro-semanal.txt').write_text('REGISTRO SEMANAL — PIEL DE MAR\n\nFecha | Situación | Qué observé | Qué ayudó | Qué probaré la próxima vez\n\nMaterial educativo; no reemplaza una evaluación profesional.\n')
sections=[('desarrollo','Desarrollo infantil',['Hitos del desarrollo','Observación en casa','Señales para consultar']),('crianza','Crianza respetuosa',['Límites que enseñan','Rutina de conexión','Elegir entre dos']),('regulacion','Regulación emocional',['Antes del momento intenso','Semáforo corporal','Después de una crisis']),('juego','Juego y estimulación',['Clasificar y encontrar','Circuito casero','Historias de tres pasos']),('lecturas','Lecturas y explicaciones',['Qué significa acompañar','Conceptos básicos','Conversar en familia']),('guias','Guías y materiales',['Registro semanal','Rincón de calma','Actividad de la semana'])]
parts=[]
for i,(key,title,items) in enumerate(sections,1):
 cards=[]
 for item in items:
  if item=='Registro semanal': action='<a href="assets/recursos/registro-semanal.txt" download>Descargar</a>'
  else: action=f'<a href="#{key}-{items.index(item)+1}">Ver recurso</a>'
  cards.append(f'<article class="resource-tile"><b>RECURSO</b><h3>{item}</h3><p>Material educativo y práctico para explorar este tema a tu ritmo.</p>{action}</article>')
 details=''.join(f'<div id="{key}-{j}" class="resource-detail"><h3>{item}</h3><p>Propuesta orientativa: observá el contexto, probá una estrategia sencilla y registrá qué ayuda. Adaptá la actividad a la edad y necesidades del niño.</p></div>' for j,item in enumerate(items,1))
 parts.append(f'<section id="{key}" class="resource-category"><div class="resource-category-heading"><span>{i:02}</span><div><p>Biblioteca</p><h2>{title}</h2></div></div><div class="resource-grid">{"".join(cards)}</div>{details}</section>')
page='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Biblioteca de recursos de Piel de Mar: lecturas, juegos, actividades y guías."><meta name="referrer" content="strict-origin-when-cross-origin"><link rel="icon" href="assets/img/logos/Isotipo2/Azul.png"><link rel="stylesheet" href="css/styles.min.css"><title>Recursos | Piel de Mar</title></head><body class="resources-library-page"><header class="resources-library-header"><a class="resources-brand" href="index.html"><img src="assets/img/logos/Isotipo2/Azul.webp" alt="Piel de Mar" width="50" height="50"><span>Piel de Mar · Recursos</span></a><a class="resources-back" href="index.html">Volver al sitio</a></header><main class="resources-library"><aside class="resources-sidebar"><p>Biblioteca</p><h1>Recursos</h1><nav aria-label="Secciones">'''+''.join(f'<a href="#{k}">{t}</a>' for k,t,_ in sections)+'''</nav></aside><div class="resources-catalog"><section class="resources-catalog-intro"><p>Biblioteca para acompañar en casa</p><h2>Explorá por tema</h2><p>Catálogo de materiales, juegos, explicaciones y guías. Cada sección tiene recursos propios y navegación directa.</p></section>'''+''.join(parts)+'''<p class="resources-disclaimer">Contenido educativo y orientativo. No reemplaza una evaluación individual, diagnóstico ni consulta profesional.</p></div></main></body></html>'''
Path('recursos.html').write_text(page)
css=Path('css/styles.css'); s=css.read_text()
if '.resources-library-page' not in s:
 s+='''.resources-library-page{background:#f7f7f3;color:#26363a}.resources-library-header{position:sticky;top:0;z-index:20;display:flex;justify-content:space-between;align-items:center;padding:1rem clamp(1rem,3vw,3rem);background:rgba(247,247,243,.96);border-bottom:1px solid rgba(38,54,58,.12)}.resources-brand{display:flex;align-items:center;gap:.75rem;color:inherit;text-decoration:none;font-weight:700}.resources-brand img{border-radius:50%}.resources-back{color:inherit;text-decoration:none;border:1px solid currentColor;padding:.55rem .9rem;border-radius:999px}.resources-library{display:grid;grid-template-columns:260px 1fr;max-width:1440px;margin:auto}.resources-sidebar{position:sticky;top:78px;align-self:start;padding:3rem 1.5rem;min-height:calc(100vh - 78px);border-right:1px solid rgba(38,54,58,.12)}.resources-sidebar h1{margin:.2rem 0 1.5rem}.resources-sidebar nav{display:grid;gap:.35rem}.resources-sidebar nav a{color:inherit;text-decoration:none;padding:.7rem .8rem;border-radius:.65rem}.resources-sidebar nav a:hover,.resources-sidebar nav a:focus-visible{background:rgba(5,73,84,.08)}.resources-catalog{padding:clamp(2rem,4vw,4rem)}.resources-catalog-intro{max-width:760px;padding-bottom:2rem}.resources-catalog-intro h2{font-size:clamp(2rem,4vw,3.3rem);margin:.25rem 0 .75rem}.resources-catalog-intro p{line-height:1.65}.resource-category{scroll-margin-top:100px;padding:2.5rem 0;border-top:1px solid rgba(38,54,58,.12)}.resource-category-heading{display:flex;gap:1rem;margin-bottom:1.25rem}.resource-category-heading>span{opacity:.55}.resource-category-heading h2{margin:0}.resource-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.resource-tile{min-height:210px;display:flex;flex-direction:column;padding:1.3rem;background:#fff;border:1px solid rgba(38,54,58,.1);border-radius:1rem;box-shadow:0 8px 28px rgba(38,54,58,.06)}.resource-tile b{font-size:.7rem;letter-spacing:.08em;opacity:.7}.resource-tile h3{margin:1rem 0 .5rem}.resource-tile p{line-height:1.55;flex:1}.resource-tile a{margin-top:1rem;color:#054954;font-weight:700}.resource-detail{margin-top:1rem;padding:1.2rem 1.3rem;background:rgba(5,73,84,.045);border-left:3px solid #054954;scroll-margin-top:100px}.resource-detail h3{margin-top:0}.resource-detail p{line-height:1.65}.resources-disclaimer{padding:2rem 0 4rem;opacity:.7}@media(max-width:900px){.resources-library{grid-template-columns:1fr}.resources-sidebar{position:sticky;top:78px;min-height:auto;padding:1rem;border-right:0;border-bottom:1px solid rgba(38,54,58,.12);background:rgba(247,247,243,.96)}.resources-sidebar nav{display:flex;overflow:auto}.resources-sidebar nav a{white-space:nowrap}.resource-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.resources-catalog{padding:1.5rem 1rem}.resource-grid{grid-template-columns:1fr}}\n'''
css.write_text(s)
